-- Player-visible item descriptions that the world database still carries in English.
-- Text comes from the 2026-11-04 world dump; every entry keeps its original layout.
-- The update is keyed by entry and only rewrites a description that still matches its source.
SET @@SESSION.`innodb_lock_wait_timeout` = 600;

CREATE TABLE IF NOT EXISTS `zz_coa_zhcn_item_desc_map` (
  `entry` int unsigned NOT NULL,
  `src` varchar(1024) NOT NULL,
  `dst` varchar(1024) NOT NULL,
  PRIMARY KEY (`entry`)
) DEFAULT CHARSET=`utf8mb4` COLLATE=`utf8mb4_unicode_ci`;

DELETE FROM `zz_coa_zhcn_item_desc_map`;

